    vector<int> distinctNumbers(vector<int>& nums, int k) {
        int n = nums.size();
        unordered_map<int, int> freq;
        int distinct = 0;
        vector<int> ans;
        ans.reserve(n - k + 1);

        for (int i = 0; i < k; ++i) {
            if (freq[nums[i]] == 0) distinct++;
            freq[nums[i]]++;
        }
        ans.push_back(distinct);

        for (int i = k; i < n; ++i) {
            int outVal = nums[i - k];
            freq[outVal]--;
            if (freq[outVal] == 0) distinct--;

            int inVal = nums[i];
            if (freq[inVal] == 0) distinct++;
            freq[inVal]++;

            ans.push_back(distinct);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] distinctNumbers(int[] nums, int k) {
        int n = nums.length;
        Map<Integer, Integer> freq = new HashMap<>();
        int distinct = 0;
        int[] ans = new int[n - k + 1];

        for (int i = 0; i < k; ++i) {
            int c = freq.getOrDefault(nums[i], 0);
            if (c == 0) distinct++;
            freq.put(nums[i], c + 1);
        }
        ans[0] = distinct;

        for (int i = k; i < n; ++i) {
            int outVal = nums[i - k];
            int outCount = freq.get(outVal);
            if (outCount == 1) {
                distinct--;
                freq.remove(outVal);
            } else {
                freq.put(outVal, outCount - 1);
            }

            int inVal = nums[i];
            int inCount = freq.getOrDefault(inVal, 0);
            if (inCount == 0) distinct++;
            freq.put(inVal, inCount + 1);

            ans[i - k + 1] = distinct;
        }
        return ans;
    }
}

