var distinctNumbers = function(nums, k) {
    const n = nums.length;
    const freq = new Map();
    let distinct = 0;
    const ans = [];

    for (let i = 0; i < k; ++i) {
        const c = freq.get(nums[i]) || 0;
        if (c === 0) distinct++;
        freq.set(nums[i], c + 1);
    }
    ans.push(distinct);

    for (let i = k; i < n; ++i) {
        const outVal = nums[i - k];
        const outCount = freq.get(outVal);
        if (outCount === 1) {
            distinct--;
            freq.delete(outVal);
        } else {
            freq.set(outVal, outCount - 1);
        }

        const inVal = nums[i];
        const inCount = freq.get(inVal) || 0;
        if (inCount === 0) distinct++;
        freq.set(inVal, inCount + 1);

        ans.push(distinct);
    }
    return ans;
};
